def generate_noisy_cosine(N):
    x = (ctypes.c_double * N)() 
    for i in range(N):
        x[i] = ctypes.c_double(2 * 3.141592653589793 * i / N)
    gsl.gRandom.genrand_int()
    for i in range(N):
        x[i] += gsl.gRandom.genrand() * 0.1
    return x

def calculate_moving_statistics(data, K):
    mean = (ctypes.c_double * len(data))()
    min = (ctypes.c_double * len(data))()
    max = (ctypes.c_double * len(data))()
    for i in range(len(data)):
        gsl.gStatistics.moving_statistics(K, data[i - K + 1:i + 1], mean[i], min[i], max[i])
    return zip(range(len(data)), data, mean, min, max)

if __name__ == '__main__':
    N = int(input())
    K = int(input())
    signal = generate_noisy_cosine(N)
    results = calculate_moving_statistics(signal, K)
    for i, signal_value, mean, min, max in results:
        print(f'{i}, {signal_value}, {mean}, {min}, {max}')

