class GSLMatrix(object):
    def __init__(self, matrix):
        self.matrix = gsl.gsl_matrix_alloc(len(matrix), len(matrix[0]))
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                gsl.gsl_matrix_set(self.matrix, i, j, matrix[i][j])

    def extract_matrix(self):
        m = np.zeros((self.matrix.size1, self.matrix.size2)) 
        for i in range(self.matrix.size1):
            for j in range(self.matrix.size2):
                m[i,j] = gsl.gsl_matrix_get(self.matrix, i, j)
        return m

