    def gsl_matrix_to_numpy(gsl_matrix: ctypes.POINTER(ctypes.c_double)) -> List[List[float]]:
        rows = gsl_matrix.contents.size // len(gsl_matrix.contents)
        cols = len(gsl_matrix.contents) 
        matrix = [[0.0 for _ in range(cols)] for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                matrix[i][j] = gsl_matrix.contents[i * cols + j]
