import ctypes
from ctypes import c_double, c_int
gslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

class gsl_function(object):
    def __init__(self, func):
        self.func = func

    def __call__(self, x):
        return self.func(x)

def chebyshev_coefficients(order, func, a, b):
    f = gsl_function(func)
    coeffs = (c_double * (order + 1))()
    gsl.chebyshev_coefficients(order, f, a, b, coeffs)
    return [coeff for coeff in coeffs]

